class PrivateLotStrategySystem(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol
        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_bars = RollingWindow[TradeBar](101)
        self.aapl_bars = RollingWindow[TradeBar](3)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def OnData(self, data: Slice):
        if data.Bars.ContainsKey(self.spy):
            self.spy_bars.Add(data.Bars[self.spy])

        if data.Bars.ContainsKey(self.aapl):
            aapl_bar = data.Bars[self.aapl]
            self.aapl_bars.Add(aapl_bar)
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)

        if not all(data.Bars.ContainsKey(symbol) for symbol in self.symbols):
            return

        spy_bar = data.Bars[self.spy]
        aapl_bar = data.Bars[self.aapl]

        # Evaluate sells before buys.
        if self.strategy_a_shares > 0 and self._spy_crosses_below_sma100():
            self.MarketOrder(self.spy, -self.strategy_a_shares, tag="strategy_a_sell")

        if self.strategy_b_shares > 0 and self.aapl_rsi.IsReady and self.aapl_rsi.Current.Value > 60:
            self.MarketOrder(self.aapl, -self.strategy_b_shares, tag="strategy_b_sell")

        if self.strategy_a_shares == 0 and self._spy_crosses_above_sma100():
            shares = int(math.floor(
                0.40 * float(self.Portfolio.TotalPortfolioValue) / float(spy_bar.Close)
            ))
            if shares > 0:
                self.MarketOrder(self.spy, shares, tag="strategy_a_buy")

        if self.strategy_b_shares == 0 and self._aapl_red_three_days():
            if float(self.Portfolio.Cash) >= 20000:
                shares = int(math.floor(20000 / float(aapl_bar.Close)))
                if shares > 0:
                    self.MarketOrder(self.aapl, shares, tag="strategy_b_buy")

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status not in [OrderStatus.PartiallyFilled, OrderStatus.Filled]:
            return

        order = self.Transactions.GetOrderById(order_event.OrderId)
        if order is None:
            return

        if order.Tag.startswith("strategy_a_"):
            self.strategy_a_shares = max(
                0, self.strategy_a_shares + order_event.FillQuantity
            )
        elif order.Tag.startswith("strategy_b_"):
            self.strategy_b_shares = max(
                0, self.strategy_b_shares + order_event.FillQuantity
            )

    def _spy_crosses_above_sma100(self):
        if not self.spy_bars.IsReady:
            return False

        today_sma = sum(self.spy_bars[i].Close for i in range(100)) / 100
        yesterday_sma = sum(self.spy_bars[i].Close for i in range(1, 101)) / 100

        return (
            self.spy_bars[1].Close <= yesterday_sma
            and self.spy_bars[0].Close > today_sma
        )

    def _spy_crosses_below_sma100(self):
        if not self.spy_bars.IsReady:
            return False

        today_sma = sum(self.spy_bars[i].Close for i in range(100)) / 100
        yesterday_sma = sum(self.spy_bars[i].Close for i in range(1, 101)) / 100

        return (
            self.spy_bars[1].Close >= yesterday_sma
            and self.spy_bars[0].Close < today_sma
        )

