        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_closes = RollingWindow[float](101)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)
        self.aapl_red_streak = 0

    def OnData(self, data: Slice):
        for symbol in self.symbols:
            if symbol not in data.Bars:
                continue

            bar = data.Bars[symbol]

            if symbol == self.spy:
                self.spy_closes.Add(float(bar.Close))

            elif symbol == self.aapl:
                self.aapl_rsi.Update(IndicatorDataPoint(self.Time, bar.Close))

                if bar.Close < bar.Open:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

        if any(symbol not in data.Bars for symbol in self.symbols):
            return

        if not self.spy_closes.IsReady or not self.aapl_rsi.IsReady:
            return

        spy_bar = data.Bars[self.spy]
        aapl_bar = data.Bars[self.aapl]

        spy_sma_today = sum(self.spy_closes[i] for i in range(100)) / 100.0
        spy_sma_yesterday = sum(self.spy_closes[i] for i in range(1, 101)) / 100.0
        spy_close_yesterday = self.spy_closes[1]

        spy_crosses_above = (
            spy_close_yesterday <= spy_sma_yesterday
            and spy_bar.Close > spy_sma_today
        )
        spy_crosses_below = (
            spy_close_yesterday >= spy_sma_yesterday
            and spy_bar.Close < spy_sma_today
        )

        # Sells before buys.
        if self.Portfolio[self.spy].Quantity > 0 and spy_crosses_below:
            self.MarketOrder(self.spy, -self.Portfolio[self.spy].Quantity)

        if self.Portfolio[self.aapl].Quantity > 0 and self.aapl_rsi.Current.Value > 60:
            self.MarketOrder(self.aapl, -self.Portfolio[self.aapl].Quantity)

        if self.Portfolio[self.spy].Quantity == 0 and spy_crosses_above:
            shares = int((self.Portfolio.TotalPortfolioValue * 0.40) / spy_bar.Close)
            if shares > 0:
                self.MarketOrder(self.spy, shares)

        if self.Portfolio[self.aapl].Quantity == 0 and self.aapl_red_streak >= 3:
            if self.Portfolio.Cash >= 20_000:
                shares = int(20_000 / aapl_bar.Close)
                if shares > 0:
                    self.MarketOrder(self.aapl, shares)
